package cli

import (
	"os"
	"testing"
)

func TestSmokeRealTranscriptStrip(t *testing.T) {
	path := os.Getenv("SMOKE_TRANSCRIPT")
	if path == "" {
		t.Skip("set SMOKE_TRANSCRIPT to run")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	out := preprocessTranscriptForDistill(string(data))
	kept := 0
	for _, l := range splitLinesNonEmpty(out) {
		kept += len(l)
	}
	chunks := chunkTranscript(out, defaultDistillChunkSize)
	t.Logf("raw %.1f MB -> kept %.0f KB (%.1f%%) -> %d chunks", float64(len(data))/1e6, float64(kept)/1e3, 100*float64(kept)/float64(len(data)), len(chunks))
	if kept == 0 {
		t.Error("strip kept nothing — conversation text lost")
	}
}

func splitLinesNonEmpty(s string) []string {
	var out []string
	for _, l := range strings.Split(s, "\n") {
		if strings.TrimSpace(l) != "" {
			out = append(out, l)
		}
	}
	return out
}
EOF
